using ChipDock.Core;
namespace ChipDock;

/// Managed buffers and native ABI declarations are generated by Interoptopus.
internal static class SerialBackend
{
    internal static Task<string> Program(string json) => Task.Run(() =>
    {
        using var request = new SerialProgramRequest { json = json }.Wire();
        using var wire = Interop.chipdock_serial_program(request).AsOk();
        var result = wire.Unwire(); Check(result.error); return result.json;
    });
    internal static Task<string> Workbench(ulong id, string json) => Task.Run(() =>
    {
        using var request = new SerialProgramRequest { json = json }.Wire();
        using var wire = Interop.chipdock_serial_workbench(id, request).AsOk();
        var result = wire.Unwire(); Check(result.error); return result.json;
    });
    private static void Check(string? error) { if (error is not null) throw new InvalidOperationException(error); }
    internal static bool IsBusy() => Interop.chipdock_serial_is_busy();
    internal static Task ConfigureLocalControl(byte mode) => Task.Run(() =>
    {
        using var wire = Interop.chipdock_serial_ipc_configure(mode).AsOk();
        Check(wire.Unwire().error);
    });
    internal static SerialPlotRequest TakePlot()
    {
        using var wire = Interop.chipdock_serial_ipc_take_plot().AsOk();
        return wire.Unwire();
    }
    internal static void FinishPlot(ulong id, string? failure)
    {
        using var request = new SerialPlotCompletion { id = id, failure = failure }.Wire();
        using var wire = Interop.chipdock_serial_ipc_finish_plot(request).AsOk();
        Check(wire.Unwire().error);
    }
    internal static void Shutdown()
    {
        using var wire = Interop.chipdock_serial_shutdown().AsOk();
        Check(wire.Unwire().error);
    }
    internal static Task<ulong> Create() => Task.Run(() =>
    {
        using var wire = Interop.chipdock_serial_create_session().AsOk();
        var result = wire.Unwire(); Check(result.error); return result.id;
    });
    internal static Task Close(ulong id) => Task.Run(() =>
    {
        using var wire = Interop.chipdock_serial_close_session(id).AsOk();
        Check(wire.Unwire().error);
    });
    internal static Task<SerialStatus> SetLine(ulong id, bool rts, bool enabled) => Task.Run(() =>
    {
        using var wire = Interop.chipdock_serial_session_set_line(id, rts, enabled).AsOk();
        var result = wire.Unwire(); Check(result.error); return result.payload!;
    });
    internal static Task<List<PortInfo>> Ports() => Task.Run(() =>
    {
        using var wire = Interop.chipdock_serial_ports().AsOk();
        var response = wire.Unwire(); Check(response.error); return response.payload;
    });
    internal static Task<PollBatch> Poll(ulong id, ulong cursor = 0) => Task.Run(() =>
    {
        using var wire = Interop.chipdock_serial_session_records(id, cursor, 256).AsOk();
        var response = wire.Unwire(); Check(response.error); return response.payload ?? throw new InvalidOperationException("核心未返回串口状态");
    });
    internal static Task<SerialStatus> Connect(ulong id, string path, SerialConfig config, bool reconnect) => Task.Run(() =>
    {
        using var request = new SerialConnectRequest { session_id = id, path = path, config = config, reconnect = reconnect }.Wire();
        using var wire = Interop.chipdock_serial_connect(request).AsOk();
        var response = wire.Unwire(); Check(response.error);
        var status = response.payload ?? throw new InvalidOperationException("核心未返回连接状态");
        return status;
    });
    internal static Task<SerialStatus> Disconnect(ulong id) => Task.Run(() =>
    {
        using var wire = Interop.chipdock_serial_session_disconnect(id).AsOk();
        var response = wire.Unwire(); Check(response.error);
        var status = response.payload ?? throw new InvalidOperationException("核心未返回连接状态");
        return status;
    });
    internal static Task Send(ulong id, string text, SendFormat format, LineEnding lineEnding, ChecksumAlgorithm checksum, SendOptions? options = null) => Task.Run(() =>
    {
        using var request = new SerialSendRequest { session_id = id, text = text, format = format, line_ending = lineEnding, checksum = checksum, options = options }.Wire();
        using var wire = Interop.chipdock_serial_send(request).AsOk(); Check(wire.Unwire().error);
    });
}
